  const res = await fetch(`${API_BASE_URL}/api/v1/subscriptions${qs}`, {
    method: "GET",
    credentials: "include",
    headers: getAuthHeaders(),
  });

  const data = await handleResponse<ApiEnvelope<SubscriptionListData>>(res);
  return data.data;
