                      <FieldBox label="Source ID" value={item.source_id ?? "-"} />
                      <FieldBox label="Changed By Role" value={item.changed_by?.role || "-"} />
                    </div>
                    <FieldBox label="Reason" value={item.reason || "-"} span />
                  </div>
                ))}
              </div>
