    </span>
  );
}

function getSkorLabelFromItem(item: NasabahItem) {
  const skorValue = getSkorValueFromItem(item);
  const skor = LIST_SKOR.find((row) => row.value === skorValue);

  return skor?.label || "Tidak Potensial (0)";
}

