    setEditedErrorRows((prev) => {
      const originalRow = importErrorRows.find((r) => r.id === rowId);
      const currentPayload = prev[rowId] || (originalRow ? originalRow.raw_payload : {});
      return {
        ...prev,
        [rowId]: {
          ...currentPayload,
          [field]: value,
        },
      };
