      <button
        type="button"
        onClick={() => onEdit(item, editMode)}
        className="text-gray-600 transition hover:scale-110 hover:text-[#C92C1E]"
        title="Edit profil"
      >
        <EditIcon className="h-5 w-5" />
      </button>

      <button
        type="button"
        onClick={() => onDelete(item)}
        className="text-gray-500 transition hover:scale-110 hover:text-red-600"
        title="Hapus data"
      >
        <TrashIcon className="h-5 w-5" />
      </button>
    </div>
  );
}

export function EditProfileModal<T extends EditProfileItem>({
  open,
  item,
  errors,
  listPic,
  onClose,
  onSubmit,
  onChangeField,
}: EditProfileModalProps<T>) {
  if (!open || !item) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden bg-black/40 p-3 sm:p-6">
      <div className="mx-auto my-6 flex max-h-[calc(100vh-3rem)] w-full max-w-lg flex-col overflow-hidden rounded-3xl border border-gray-200 bg-white shadow-2xl">
        <div className="flex items-center justify-between gap-4 border-b p-4 sm:p-5">
          <div>
            <h2 className="text-lg font-black text-gray-900">
              Edit Profil Owner
            </h2>
            <p className="text-xs text-gray-400 font-medium">
              Form ini hanya mengubah data utama profil owner.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="w-9 h-9 rounded-full bg-gray-100 hover:bg-gray-200 text-gray-600 font-black"
          >
            ×
          </button>
        </div>

        <form onSubmit={onSubmit} className="min-h-0 flex-1 space-y-4 overflow-y-auto p-4 sm:p-5">
          <div className="grid grid-cols-1 gap-3">
            <FormInput
              label="Kode Owner *"
              icon="code"
              value={item.kodeOwner || ""}
              onChange={(value) => onChangeField("kodeOwner", value as T["kodeOwner"])}
              error={errors.kodeOwner}
            />
            <FormInput
              label="Nama Owner *"
              icon="user"
              value={item.namaOwner || ""}
              onChange={(value) => onChangeField("namaOwner", value as T["namaOwner"])}
              error={errors.namaOwner}
            />
            <FormInput
              label="Nama Brand *"
              icon="brand"
              value={item.projectBrand || ""}
              onChange={(value) => onChangeField("projectBrand", value as T["projectBrand"])}
              error={errors.projectBrand}
            />
            <OutletNamesEditor
              item={item}
              error={errors.outlet}
              onChangeField={onChangeField}
            />
            <PhoneInput
              label="Nomor Telepon Owner *"
              value={item.noHpOwner || ""}
              onChange={(value) => onChangeField("noHpOwner", value as T["noHpOwner"])}
              error={errors.noHpOwner}
            />
            <FormSelect
              label="PIC Sales *"
              icon="sales"
              required
              value={item.pic || ""}
              options={listPic}
              onChange={(value) => onChangeField("pic", value as T["pic"])}
              error={errors.pic}
            />
          </div>

          <div className="flex flex-col-reverse gap-2 border-t pt-4 sm:flex-row sm:justify-end">
            <button
              type="button"
              onClick={onClose}
              className="w-full rounded-xl border px-4 py-2 text-xs font-bold text-gray-500 hover:bg-gray-50 sm:w-auto cursor-pointer"
            >
              Batal
            </button>
            <button
              type="submit"
              className="w-full rounded-xl bg-[#C92C1E] px-5 py-2 text-xs font-extrabold text-white shadow-sm hover:bg-[#A82216] sm:w-auto cursor-pointer"
            >
              Simpan Perubahan
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

