};


const isValidOwnerOutletName = (value?: string) => {
  const normalizedValue = String(value || "").trim().toLowerCase();

  if (!normalizedValue) return false;

  return ![
    "-",
    "nama outlet",
    "nama outlet aktif",
    "nothing laundry",
    "tampilkan jika ada",
  ].includes(normalizedValue);
};

