"use client";

import React, { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import {
  fetchOwners,
  type BackendOwner,
  createOwner,
  uploadImportFile,
  getImportBatch,
  commitImportBatch,
  getImportErrorRows,
  getImportValidRows,
  type ImportBatchResponse,
  type ImportRowError,
  updateOwner,
  restoreOwner,
  softDeleteOwner,
  bulkSoftDeleteOwners,
  bulkCreateOwnerOutlets,
} from "@/app/lib/api";
import { useLocation } from "@/app/lib/useLocation";
import { usePageTitle } from "@/app/lib/hooks/usePageTitle";
import * as XLSX from "xlsx";
import AnalyticsTab from "./AnalyticsTab";
import ImportHistoryModal from "@/app/components/ImportHistoryModal";

const modalInputClass =
  "w-full rounded-2xl border border-gray-200 bg-[#FAFAFA] px-4 py-3 text-sm font-bold text-gray-900 outline-none transition placeholder:text-gray-400 focus:border-[#C92C1E] focus:bg-white focus:ring-2 focus:ring-red-100 disabled:bg-gray-100 disabled:text-gray-400";

const modalSelectClass =
  "w-full rounded-2xl border border-gray-200 bg-[#FAFAFA] px-4 py-3 text-sm font-bold text-gray-900 outline-none transition focus:border-[#C92C1E] focus:bg-white focus:ring-2 focus:ring-red-100 disabled:bg-gray-100 disabled:text-gray-400";

const modalTextareaClass =
  "w-full rounded-2xl border border-gray-200 bg-[#FAFAFA] px-4 py-3 text-sm font-bold text-gray-900 outline-none transition placeholder:text-gray-400 focus:border-[#C92C1E] focus:bg-white focus:ring-2 focus:ring-red-100 disabled:bg-gray-100 disabled:text-gray-400";

function ModalShell({
  open,
  title,
  subtitle,
  label = "Owner",
  maxWidth = "max-w-3xl",
  disabled = false,
  onClose,
  children,
}: {
  open: boolean;
  title: string;
  subtitle: string;
  label?: string;
  maxWidth?: string;
  disabled?: boolean;
  onClose: () => void;
  children: React.ReactNode;
}) {
  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 bg-slate-950/70"
      onClick={() => !disabled && onClose()}
    >
      <div className="flex min-h-full items-center justify-center overflow-y-auto p-4 md:p-6">
        <div
          className={`w-full ${maxWidth} overflow-hidden rounded-[32px] border border-slate-200 bg-white shadow-2xl`}
          onClick={(event) => event.stopPropagation()}
        >
          <div className="border-b border-slate-100 bg-[linear-gradient(135deg,#fff_0%,#fff8f5_55%,#fee2e2_100%)] px-5 py-4 md:px-6">
            <div className="flex items-start justify-between gap-4">
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.24em] text-[#C92C1E]">
                  {label}
                </p>

                <h2 className="mt-2 text-lg font-black text-slate-950 md:text-xl">
                  {title}
                </h2>

                <p className="mt-1 text-xs font-medium text-slate-500">
                  {subtitle}
                </p>
              </div>

              <button
                type="button"
                onClick={onClose}
                disabled={disabled}
                className="rounded-2xl border border-slate-200 bg-white px-4 py-2 text-xs font-black text-slate-500 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
              >
                Tutup
              </button>
            </div>
          </div>

          <div className="max-h-[calc(100vh-8rem)] overflow-y-auto p-5 md:p-6">
            {children}
          </div>
        </div>
      </div>
    </div>
  );
}

function PlusIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" />
    </svg>
  );
}

function DownloadIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
    </svg>
  );
}

function UploadIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
    </svg>
  );
}

function TrashIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
    </svg>
  );
}

function HistoryIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
  );
}

function ChartIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z" />
    </svg>
  );
}

function EyeIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
    </svg>
  );
}

function EditIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
    </svg>
  );
}

function RestoreIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
    </svg>
  );
}

function SpinnerIcon({ className = "h-4 w-4" }: { className?: string }) {
  return (
    <svg
      className={`${className} animate-spin`}
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
    >
      <circle
        className="opacity-25"
        cx="12"
        cy="12"
        r="10"
        stroke="currentColor"
        strokeWidth="4"
      />
      <path
        className="opacity-75"
        fill="currentColor"
        d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
      />
    </svg>
  );
}

export default function OwnerOutletPage() {
  usePageTitle("Owner");
  const router = useRouter();

  const [owners, setOwners] = useState<BackendOwner[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0,
  });
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("-created_at");
  const [filters, setFilters] = useState({
    code: "",
    name: "",
    brand_name: "",
    phone: "",
    city: "",
  });
  const [openFilter, setOpenFilter] = useState<string | null>(null);
  const [selectedOwnerIds, setSelectedOwnerIds] = useState<number[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [dragMode, setDragMode] = useState<"select" | "deselect">("select");
  const [activeTab, setActiveTab] = useState<"list" | "analytics">("list");

  const [isImportModalOpen, setIsImportModalOpen] = useState(false);
  const [isImportHistoryModalOpen, setIsImportHistoryModalOpen] =
    useState(false);
  const [importFile, setImportFile] = useState<File | null>(null);
  const [importBatch, setImportBatch] =
    useState<ImportBatchResponse | null>(null);
  const [isImportLoading, setIsImportLoading] = useState(false);
  const [importError, setImportError] = useState<string | null>(null);
  const [importErrorRows, setImportErrorRows] = useState<ImportRowError[]>([]);
  const [editedErrorRows, setEditedErrorRows] = useState<Record<number, any>>(
    {},
  );
  const [isApplyingCorrections, setIsApplyingCorrections] = useState(false);
  const [correctionProgress, setCorrectionProgress] = useState(0);
  const [correctionStatusText, setCorrectionStatusText] = useState("");
  const pollTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [isAddOwnerModalOpen, setIsAddOwnerModalOpen] = useState(false);
  const [isAddOwnerSubmitting, setIsAddOwnerSubmitting] = useState(false);
  const [addOwnerForm, setAddOwnerForm] = useState({
    code: "",
    name: "",
    brand_name: "",
    phone: "",
    province: "",
    city: "",
    address: "",
    outlet_name: "",
    outlet_phone: "",
    outlet_province: "",
    outlet_city: "",
    outlet_address: "",
  });

  const [isEditOwnerModalOpen, setIsEditOwnerModalOpen] = useState(false);
  const [isEditOwnerSubmitting, setIsEditOwnerSubmitting] = useState(false);
  const [editOwnerForm, setEditOwnerForm] = useState({
    id: 0,
    code: "",
    name: "",
    brand_name: "",
    phone: "",
    province: "",
    city: "",
    address: "",
  });

  const {
    provinces,
    cities,
    loadCitiesByProvinceName,
    loadingProvinces,
    loadingCities,
  } = useLocation();

  const {
    provinces: outletProvinces,
    cities: outletCities,
    loadCitiesByProvinceName: loadOutletCities,
    loadingProvinces: outletLoadingProvinces,
    loadingCities: outletLoadingCities,
  } = useLocation();

  useEffect(() => {
    const handleMouseUp = () => setIsDragging(false);
    window.addEventListener("mouseup", handleMouseUp);
    return () => window.removeEventListener("mouseup", handleMouseUp);
  }, []);

  useEffect(() => {
    return () => {
      if (pollTimerRef.current) clearTimeout(pollTimerRef.current);
    };
  }, []);

  useEffect(() => {
    if (isEditOwnerModalOpen && editOwnerForm.province && provinces.length > 0) {
      loadCitiesByProvinceName(editOwnerForm.province);
    }
  }, [
    isEditOwnerModalOpen,
    editOwnerForm.province,
    provinces,
    loadCitiesByProvinceName,
  ]);

  const loadOwners = useCallback(async () => {
    setIsLoading(true);
    try {
      const res = await fetchOwners({
        page: pagination.page,
        limit: pagination.limit,
        q: search,
        code: filters.code,
        name: filters.name,
        brand_name: filters.brand_name,
        phone: filters.phone,
        city: filters.city,
        sort,
      });
      setOwners(res.data.items);
      setPagination(res.data.pagination);
    } catch (err) {
      console.error("Gagal memuat data owner:", err);
    } finally {
      setIsLoading(false);
    }
  }, [pagination.page, pagination.limit, search, filters, sort]);

  useEffect(() => {
    loadOwners();
  }, [loadOwners]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setPagination((prev) => ({ ...prev, page: 1 }));
    loadOwners();
  };

  const handleRowMouseDown = (id: number, currentlySelected: boolean) => {
    setIsDragging(true);
    const mode = currentlySelected ? "deselect" : "select";
    setDragMode(mode);

    setSelectedOwnerIds((prev) => {
      if (mode === "select" && !prev.includes(id)) return [...prev, id];
      if (mode === "deselect" && prev.includes(id)) {
        return prev.filter((selectedId) => selectedId !== id);
      }
      return prev;
    });
  };

  const handleRowMouseEnter = (id: number) => {
    if (!isDragging) return;

    setSelectedOwnerIds((prev) => {
      if (dragMode === "select" && !prev.includes(id)) return [...prev, id];
      if (dragMode === "deselect" && prev.includes(id)) {
        return prev.filter((selectedId) => selectedId !== id);
      }
      return prev;
    });
  };

  const handleAddOwnerSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!addOwnerForm.code.trim() || !addOwnerForm.name.trim()) {
      alert("Kode dan Nama Owner wajib diisi.");
      return;
    }

    if (!addOwnerForm.outlet_name?.trim()) {
      alert("Nama Outlet Pertama wajib diisi.");
      return;
    }

    setIsAddOwnerSubmitting(true);

    try {
      const createdOwner = await createOwner(addOwnerForm);

      if (createdOwner.data && createdOwner.data.id) {
        await bulkCreateOwnerOutlets(createdOwner.data.id, [
          {
            code: `${addOwnerForm.code}-1`,
            name: addOwnerForm.outlet_name,
            phone: addOwnerForm.outlet_phone || "",
            province: addOwnerForm.outlet_province || "",
            city: addOwnerForm.outlet_city || "",
            address: addOwnerForm.outlet_address || "",
          },
        ]);
      }

      alert("Owner dan Outlet berhasil ditambahkan");
      setIsAddOwnerModalOpen(false);
      setAddOwnerForm({
        code: "",
        name: "",
        brand_name: "",
        phone: "",
        province: "",
        city: "",
        address: "",
        outlet_name: "",
        outlet_phone: "",
        outlet_province: "",
        outlet_city: "",
        outlet_address: "",
      });
      loadOwners();
    } catch (err: any) {
      alert(err.message || "Gagal menambahkan owner");
    } finally {
      setIsAddOwnerSubmitting(false);
    }
  };

  const handleOpenEditOwner = (owner: BackendOwner) => {
    setEditOwnerForm({
      id: owner.id,
      code: owner.code,
      name: owner.name,
      brand_name: owner.brand_name || "",
      phone: owner.phone || "",
      province: owner.province || "",
      city: owner.city || "",
      address: owner.address || "",
    });

    if (owner.province) {
      loadCitiesByProvinceName(owner.province);
    }

    setIsEditOwnerModalOpen(true);
  };

  const handleEditOwnerSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!editOwnerForm.code.trim() || !editOwnerForm.name.trim()) {
      alert("Kode dan Nama Owner wajib diisi.");
      return;
    }

    setIsEditOwnerSubmitting(true);

    try {
      await updateOwner(editOwnerForm.id, {
        code: editOwnerForm.code,
        name: editOwnerForm.name,
        brand_name: editOwnerForm.brand_name,
        phone: editOwnerForm.phone,
        province: editOwnerForm.province,
        city: editOwnerForm.city,
        address: editOwnerForm.address,
      });

      alert("Owner berhasil diupdate");
      setIsEditOwnerModalOpen(false);
      loadOwners();
    } catch (err: any) {
      alert(err.message || "Gagal update owner");
    } finally {
      setIsEditOwnerSubmitting(false);
    }
  };

  const handleDeleteOwner = async (ownerId: number) => {
    if (!confirm("Apakah Anda yakin ingin menghapus owner ini?")) return;

    try {
      await softDeleteOwner(ownerId);
      loadOwners();
    } catch (err: any) {
      alert(err.message || "Gagal menghapus owner");
    }
  };

  const handleRestoreOwner = async (ownerId: number) => {
    if (!confirm("Apakah Anda yakin ingin merestore owner ini?")) return;

    try {
      await restoreOwner(ownerId);
      loadOwners();
    } catch (err: any) {
      alert(err.message || "Gagal merestore owner");
    }
  };

  const handleExportExcel = async () => {
    try {
      const resp = await fetchOwners({ limit: 100000 });
      const activeOwners = resp.data.items;

      if (activeOwners.length === 0) {
        alert("Tidak ada data owner untuk di-export.");
        return;
      }

      const dataToExport = activeOwners.map((owner) => ({
        "Kode Owner": owner.code,
        "Nama Owner": owner.name,
        "Brand/Usaha": owner.brand_name || "-",
        Kontak: owner.phone || "-",
        Provinsi: owner.province || "-",
        "Kota/Kabupaten": owner.city || "-",
        "Alamat Lengkap": owner.address || "-",
        "Total Outlet": owner.outlet_count || 0,
      }));

      const worksheet = XLSX.utils.json_to_sheet(dataToExport);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Data_Owner");
      XLSX.writeFile(
        workbook,
        `Data_Total_Owner_${new Date().getTime()}.xlsx`,
      );
    } catch (error) {
      console.error("Gagal mengekspor data owner:", error);
      alert("Terjadi kesalahan saat mengunduh data ekspor.");
    }
  };

  const handleBulkDelete = async () => {
    if (selectedOwnerIds.length === 0) return;

    if (
      !confirm(
        `Apakah Anda yakin ingin menghapus ${selectedOwnerIds.length} owner terpilih?`,
      )
    ) {
      return;
    }

    try {
      await bulkSoftDeleteOwners(selectedOwnerIds);
      setSelectedOwnerIds([]);
      loadOwners();
    } catch (err: any) {
      alert(err.message || "Gagal menghapus owner terpilih.");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setImportFile(e.target.files[0]);
      setImportError(null);
    }
  };

  const handleUploadClick = async () => {
    if (!importFile) return;

    setIsImportLoading(true);
    setImportError(null);

    try {
      const resp = await uploadImportFile(importFile, "OWNER_OUTLET");
      setImportBatch(resp);
      pollImportStatus(resp.id);
    } catch (err: any) {
      setImportError(err.message || "Gagal mengunggah file");
      setIsImportLoading(false);
    }
  };

  const pollImportStatus = async (batchId: number) => {
    if (pollTimerRef.current) {
      clearTimeout(pollTimerRef.current);
      pollTimerRef.current = null;
    }

    try {
      const resp = await getImportBatch(batchId);
      setImportBatch(resp);

      const isInProgress = ["UPLOADED", "VALIDATING", "COMMITTING"].includes(
        resp.status,
      );

      if (isInProgress) {
        pollTimerRef.current = setTimeout(
          () => pollImportStatus(batchId),
          2500,
        );
      } else {
        pollTimerRef.current = null;
        setIsImportLoading(false);
        setCorrectionProgress(100);
        setCorrectionStatusText("Selesai!");

        setTimeout(() => {
          setCorrectionProgress(0);
          setCorrectionStatusText("");
        }, 2000);

        if (resp.status === "VALIDATED" && resp.invalid_rows > 0) {
          try {
            const errorResp = await getImportErrorRows(batchId);
            setImportErrorRows(errorResp.items);
            setImportError(
              `Masih terdapat ${resp.invalid_rows} baris dengan format yang tidak valid.`,
            );
          } catch (error) {
            console.error("Gagal memuat detail error:", error);
          }
        } else if (resp.status === "VALIDATED") {
          setImportError(null);
        } else if (resp.status === "VALIDATION_FAILED") {
          setImportError(
            resp.error_message ||
              "Validasi file gagal. Periksa format dan header file Excel Anda.",
          );
        } else if (resp.status === "COMMIT_FAILED") {
          setImportError(
            resp.error_message ||
              "Proses simpan data gagal. Silakan coba lagi.",
          );
        }
      }
    } catch (err: any) {
      pollTimerRef.current = null;
      setImportError(err.message || "Gagal mengecek status import");
      setIsImportLoading(false);
    }
  };

  const handleCommitImport = async () => {
    if (!importBatch) return;

    setIsImportLoading(true);

    try {
      const resp = await commitImportBatch(importBatch.id);
      setImportBatch(resp);
      pollImportStatus(resp.id);
    } catch (err: any) {
      setImportError(err.message || "Gagal menyimpan data import");
      setIsImportLoading(false);
    }
  };

  const resetImportState = () => {
    if (pollTimerRef.current) {
      clearTimeout(pollTimerRef.current);
      pollTimerRef.current = null;
    }

    setImportFile(null);
    setImportBatch(null);
    setImportError(null);
    setIsImportLoading(false);
    setImportErrorRows([]);
    setEditedErrorRows({});
    setCorrectionProgress(0);
    setCorrectionStatusText("");
  };

  const handleEditErrorRow = (rowId: number, field: string, value: string) => {
    setEditedErrorRows((prev) => {
      const originalRow = importErrorRows.find((row) => row.id === rowId);
      const currentPayload =
        prev[rowId] || (originalRow ? originalRow.raw_payload : {});

      return {
        ...prev,
        [rowId]: {
          ...currentPayload,
          [field]: value,
        },
      };
    });
  };

  const handleApplyCorrections = async () => {
    if (!importBatch) return;

    setIsApplyingCorrections(true);
    setImportError(null);
    setCorrectionProgress(10);
    setCorrectionStatusText("Menyiapkan data perbaikan...");

    try {
      const correctedPayloads = importErrorRows.map((row) => {
        return editedErrorRows[row.id] || row.raw_payload;
      });

      setCorrectionProgress(30);
      setCorrectionStatusText("Mengambil data valid dari server...");
      const validResp = await getImportValidRows(importBatch.id);
      const validPayloads = validResp.items.map((item) => item.raw_payload);

      setCorrectionProgress(50);
      setCorrectionStatusText("Menyusun ulang file Excel...");
      const allPayloads = [...validPayloads, ...correctedPayloads];

      const worksheet = XLSX.utils.json_to_sheet(allPayloads);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Data_Owner");

      const wbout = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
      const file = new File([wbout], "import_corrected.xlsx", {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });

      setCorrectionProgress(70);
      setCorrectionStatusText("Mengunggah ulang file perbaikan...");
      setIsImportLoading(true);
      const resp = await uploadImportFile(file, "OWNER_OUTLET");
      setImportBatch(resp);

      setCorrectionProgress(90);
      setCorrectionStatusText("Memvalidasi ulang data...");
      pollImportStatus(resp.id);
    } catch (e: any) {
      console.error(e);
      setImportError(e.message || "Gagal menerapkan perbaikan.");
      setIsApplyingCorrections(false);
      setCorrectionProgress(0);
      setCorrectionStatusText("");
    }
  };

  const handleViewOutlets = (owner: BackendOwner) => {
    router.push(`/menu/owner-outlet/${owner.id}`);
  };

  const activeCount = owners.filter((owner) => owner.status === "ACTIVE").length;
  const inactiveCount = owners.length - activeCount;

  const renderFilterHeader = (key: string, label: string) => {
    const isSorted = sort.replace("-", "") === key;
    const isDesc = sort.startsWith("-");

    return (
      <th className="relative whitespace-nowrap px-4 py-4 font-bold">
        <div className="flex select-none items-center gap-2">
          <div
            className="flex cursor-pointer items-center gap-1 transition-colors hover:text-red-700"
            onClick={() => setSort(sort === key ? `-${key}` : key)}
            title={`Urutkan berdasarkan ${label}`}
          >
            {label}
            <div className="-space-y-1 flex flex-col opacity-40 transition-opacity group-hover:opacity-100">
              <svg
                className={`h-2.5 w-2.5 ${
                  isSorted && !isDesc ? "text-[#C92C1E] opacity-100" : ""
                }`}
                fill="currentColor"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
                  clipRule="evenodd"
                />
              </svg>
              <svg
                className={`h-2.5 w-2.5 ${
                  isSorted && isDesc ? "text-[#C92C1E] opacity-100" : ""
                }`}
                fill="currentColor"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
                  clipRule="evenodd"
                />
              </svg>
            </div>
          </div>

          <svg
            className={`ml-1 h-3.5 w-3.5 cursor-pointer transition-colors ${
              filters[key as keyof typeof filters]
                ? "text-[#C92C1E]"
                : "text-gray-400 hover:text-gray-600"
            }`}
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            onClick={() => setOpenFilter(openFilter === key ? null : key)}
          >
            <title>{`Filter ${label}`}</title>
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2.5}
              d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z"
            />
          </svg>
        </div>

        {openFilter === key && (
          <>
            <div
              className="fixed inset-0 z-10"
              onClick={() => setOpenFilter(null)}
            />
            <div className="absolute left-4 top-full z-20 mt-1 w-48 origin-top rounded-lg border border-gray-200 bg-white p-2 shadow-xl">
              <div className="mb-2 flex items-center gap-2">
                <svg
                  className="h-4 w-4 text-gray-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                  />
                </svg>
                <span className="text-sm font-semibold text-gray-600">
                  Cari {label}
                </span>
              </div>

              <input
                type="text"
                placeholder="Ketik untuk mencari..."
                className="w-full rounded-md border border-gray-200 px-3 py-2 text-sm font-normal focus:border-[#C92C1E] focus:outline-none focus:ring-1 focus:ring-[#C92C1E]"
                value={filters[key as keyof typeof filters]}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, [key]: e.target.value }))
                }
                autoFocus
                onKeyDown={(e) => {
                  if (e.key === "Enter") setOpenFilter(null);
                }}
              />
            </div>
          </>
        )}
      </th>
    );
  };

  return (
    <div className="space-y-6">
      <div className="overflow-hidden rounded-2xl border border-gray-200/60 bg-white shadow-sm">
        <div className="flex flex-col items-start justify-between gap-4 border-b-2 border-[#C92C1E] p-5 md:flex-row md:items-center">
          <div>
            <div className="mb-1 flex items-center gap-2 text-xs font-bold text-gray-500">
              <span>Menu</span>
              <svg
                className="h-3 w-3"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={3}
                  d="M9 5l7 7-7 7"
                />
              </svg>
              <span className="text-[#C92C1E]">Owner</span>
            </div>

            <h1 className="text-2xl font-black tracking-tight text-gray-900">
              Manajemen Owner
            </h1>

            <p className="mt-1 text-sm text-gray-500">
              Kelola data owner beserta outlet miliknya, import Excel, dan
              riwayat perubahan data.
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
        <div className="relative flex flex-col justify-between overflow-hidden rounded-2xl bg-gradient-to-br from-[#C92C1E] to-[#A82216] p-5 text-white shadow-lg">
          <div className="relative z-10">
            <p className="mb-1 text-xs font-bold uppercase tracking-wider text-red-100">
              Total Owner
            </p>
            <h2 className="text-3xl font-black">{pagination.total}</h2>
          </div>
        </div>

        <div className="group relative overflow-hidden rounded-2xl border border-red-100 bg-white p-5 shadow-sm transition-colors hover:border-[#C92C1E]">
          <p className="mb-1 text-xs font-bold uppercase tracking-wider text-gray-500">
            Owner Aktif
          </p>
          <h2 className="text-3xl font-black text-gray-900">{activeCount}</h2>
        </div>

        <div className="group relative overflow-hidden rounded-2xl border border-red-100 bg-white p-5 shadow-sm transition-colors hover:border-[#C92C1E]">
          <p className="mb-1 text-xs font-bold uppercase tracking-wider text-gray-500">
            Owner Non-Aktif
          </p>
          <h2 className="text-3xl font-black text-gray-900">{inactiveCount}</h2>
        </div>
      </div>

      <div className="flex w-max rounded-xl border border-gray-200/50 bg-gray-100 p-1.5 shadow-sm">
        <button
          onClick={() => setActiveTab("list")}
          className={`rounded-lg px-5 py-2.5 text-sm font-bold transition-all ${
            activeTab === "list"
              ? "bg-white text-[#C92C1E] shadow-sm"
              : "text-gray-500 hover:bg-gray-200/50 hover:text-gray-700"
          }`}
        >
          Daftar Owner
        </button>

        <button
          onClick={() => setActiveTab("analytics")}
          className={`flex items-center gap-2 rounded-lg px-5 py-2.5 text-sm font-bold transition-all ${
            activeTab === "analytics"
              ? "bg-white text-[#C92C1E] shadow-sm"
              : "text-gray-500 hover:bg-gray-200/50 hover:text-gray-700"
          }`}
        >
          <ChartIcon />
          Analitik
        </button>
      </div>

      {activeTab === "analytics" ? (
        <AnalyticsTab />
      ) : (
        <>
          <div className="overflow-hidden rounded-2xl border border-gray-200/60 bg-white shadow-xs">
            <div className="flex flex-wrap items-center justify-between gap-4 border-b border-gray-100 bg-gray-50/50 p-4">
              <form
                onSubmit={handleSearch}
                className="flex w-full flex-wrap items-center gap-2 lg:w-auto"
              >
                <input
                  type="text"
                  placeholder="Cari Owner..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="min-w-[200px] rounded-lg border border-gray-200 px-3 py-2 text-sm text-gray-700 focus:border-[#C92C1E] focus:outline-none focus:ring-1 focus:ring-[#C92C1E]"
                />

                <button
                  type="submit"
                  className="rounded-lg bg-[#C92C1E] px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-red-700"
                >
                  Cari
                </button>
              </form>

              <div className="flex w-full justify-end gap-2 sm:w-auto">
                {selectedOwnerIds.length > 0 && (
                  <button
                    onClick={handleBulkDelete}
                    className="flex items-center gap-2 rounded-xl border border-red-200 bg-red-50 px-4 py-2 text-sm font-bold text-red-600 shadow-sm transition-all hover:bg-red-100"
                  >
                    <TrashIcon />
                    Hapus Terpilih ({selectedOwnerIds.length})
                  </button>
                )}

                <button
                  onClick={handleExportExcel}
                  className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2 text-sm font-bold text-gray-700 shadow-sm transition-all hover:bg-gray-50"
                >
                  <DownloadIcon className="h-4 w-4 text-blue-600" />
                  Export Excel
                </button>

                <button
                  onClick={() => setIsImportHistoryModalOpen(true)}
                  className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2.5 text-sm font-bold text-gray-700 shadow-sm transition-colors hover:bg-gray-50 focus:border-[#C92C1E] focus:outline-none focus:ring-1 focus:ring-[#C92C1E]"
                >
                  <HistoryIcon />
                  Riwayat Import
                </button>

                <button
                  onClick={() => setIsImportModalOpen(true)}
                  className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2 text-sm font-bold text-gray-700 shadow-sm transition-all hover:bg-gray-50"
                >
                  <UploadIcon className="h-4 w-4 text-emerald-600" />
                  Import Excel
                </button>

                <button
                  onClick={() => setIsAddOwnerModalOpen(true)}
                  className="flex items-center gap-2 rounded-xl bg-[#C92C1E] px-4 py-2 text-sm font-bold text-white shadow-sm shadow-red-200 transition-all hover:bg-red-700"
                >
                  <PlusIcon />
                  Tambah Owner
                </button>

                <button
                  onClick={() => router.push("/menu/owner-outlet/trash")}
                  className="flex items-center gap-2 rounded-xl border border-gray-200 bg-gray-100 px-4 py-2 text-sm font-bold text-gray-700 shadow-sm transition-all hover:bg-gray-200"
                >
                  <TrashIcon className="h-4 w-4 text-gray-600" />
                  Lihat Sampah
                </button>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full min-w-[1080px] text-left text-sm text-gray-600">
                <thead className="border-y border-gray-200 bg-[#f9fafb] text-xs font-black uppercase tracking-wider text-gray-500">
                  <tr>
                    <th className="w-12 px-4 py-4 text-center">
                      <input
                        type="checkbox"
                        checked={
                          owners.length > 0 &&
                          selectedOwnerIds.length === owners.length
                        }
                        onChange={(e) => {
                          if (e.target.checked) {
                            setSelectedOwnerIds(owners.map((owner) => owner.id));
                          } else {
                            setSelectedOwnerIds([]);
                          }
                        }}
                        className="rounded border-gray-300 text-[#C92C1E] focus:ring-[#C92C1E]"
                      />
                    </th>
                    {renderFilterHeader("code", "Kode")}
                    {renderFilterHeader("name", "Nama Owner")}
                    {renderFilterHeader("brand_name", "Brand")}
                    {renderFilterHeader("phone", "Kontak")}
                    {renderFilterHeader("city", "Lokasi")}
                    <th className="px-4 py-4 text-center font-bold">Status</th>
                    <th className="px-4 py-4 text-center font-bold">Outlet</th>
                    <th className="px-4 py-4 text-center font-bold">Aksi</th>
                  </tr>
                </thead>

                <tbody className="divide-y divide-gray-100 bg-white">
                  {isLoading ? (
                    <tr>
                      <td colSpan={9} className="px-6 py-10 text-center text-gray-500">
                        Memuat data...
                      </td>
                    </tr>
                  ) : owners.length === 0 ? (
                    <tr>
                      <td colSpan={9} className="px-6 py-10 text-center text-gray-500">
                        Tidak ada data owner ditemukan.
                      </td>
                    </tr>
                  ) : (
                    owners.map((owner) => {
                      const isSelected = selectedOwnerIds.includes(owner.id);

                      return (
                        <tr
                          key={owner.id}
                          className={`select-none transition-colors ${
                            isSelected
                              ? "bg-red-50/40 hover:bg-red-50/60"
                              : "hover:bg-gray-50"
                          }`}
                          onMouseDown={(e) => {
                            if (e.button !== 0) return;
                            handleRowMouseDown(owner.id, isSelected);
                          }}
                          onMouseEnter={() => handleRowMouseEnter(owner.id)}
                        >
                          <td className="px-4 py-4 text-center">
                            <input
                              type="checkbox"
                              checked={isSelected}
                              readOnly
                              className="pointer-events-none rounded border-gray-300 text-[#C92C1E] focus:ring-[#C92C1E]"
                            />
                          </td>

                          <td className="px-4 py-4 align-top font-medium text-gray-900">
                            {owner.code}
                          </td>
                          <td className="px-4 py-4 align-top font-medium text-gray-900">
                            {owner.name}
                          </td>
                          <td className="px-4 py-4 align-top">
                            {owner.brand_name || "-"}
                          </td>
                          <td className="px-4 py-4 align-top">{owner.phone}</td>
                          <td className="px-4 py-4 align-top">
                            {owner.city
                              ? `${owner.city}, ${owner.province || ""}`
                              : "-"}
                          </td>
                          <td className="px-4 py-4 text-center align-top">
                            <span
                              className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-black uppercase tracking-tight ${
                                owner.status === "ACTIVE"
                                  ? "border border-emerald-200 bg-emerald-50 text-emerald-700"
                                  : "border border-red-200 bg-red-50 text-red-700"
                              }`}
                            >
                              {owner.status}
                            </span>
                          </td>
                          <td className="px-4 py-4 text-center align-top">
                            <span className="inline-flex items-center justify-center rounded-md bg-gray-100 px-2 py-1 text-xs font-bold text-gray-700">
                              {owner.outlet_count || 0}
                            </span>
                          </td>
                          <td
                            className="px-4 py-4 text-center"
                            onMouseDown={(e) => e.stopPropagation()}
                          >
                            <div className="flex items-center justify-center gap-2">
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleViewOutlets(owner);
                                }}
                                className="rounded-lg bg-blue-50 p-2 text-blue-600 transition-colors hover:bg-blue-100 hover:text-blue-700"
                                title="Detail Outlet"
                              >
                                <EyeIcon />
                              </button>

                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleOpenEditOwner(owner);
                                }}
                                className="rounded-lg bg-orange-50 p-2 text-orange-600 transition-colors hover:bg-orange-100 hover:text-orange-700"
                                title="Edit Owner"
                              >
                                <EditIcon />
                              </button>

                              {owner.status !== "ACTIVE" ? (
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    handleRestoreOwner(owner.id);
                                  }}
                                  className="rounded-lg bg-emerald-50 p-2 text-emerald-600 transition-colors hover:bg-emerald-100 hover:text-emerald-700"
                                  title="Restore Owner"
                                >
                                  <RestoreIcon />
                                </button>
                              ) : (
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    handleDeleteOwner(owner.id);
                                  }}
                                  className="rounded-lg bg-gray-50 p-2 text-gray-500 transition-colors hover:bg-gray-100 hover:text-gray-700"
                                  title="Hapus Owner"
                                >
                                  <TrashIcon />
                                </button>
                              )}
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>

            <div className="flex flex-col items-center justify-between gap-4 border-t border-gray-100 bg-gray-50/50 p-4 sm:flex-row">
              <div className="flex items-center gap-4">
                <span className="text-xs text-gray-500">
                  Total {pagination.total} Owner
                </span>

                <div className="flex items-center gap-2">
                  <span className="text-xs font-medium text-gray-500">
                    Tampilkan
                  </span>
                  <select
                    value={pagination.limit}
                    onChange={(e) =>
                      setPagination((prev) => ({
                        ...prev,
                        limit: Number(e.target.value),
                        page: 1,
                      }))
                    }
                    className="rounded-md border border-gray-200 bg-white px-2 py-1 text-xs text-gray-700 focus:border-[#C92C1E] focus:outline-none"
                  >
                    <option value={10}>10</option>
                    <option value={25}>25</option>
                    <option value={50}>50</option>
                    <option value={100}>100</option>
                  </select>
                  <span className="text-xs font-medium text-gray-500">baris</span>
                </div>
              </div>

              <div className="flex items-center gap-2">
                <button
                  disabled={pagination.page <= 1}
                  onClick={() =>
                    setPagination((prev) => ({
                      ...prev,
                      page: prev.page - 1,
                    }))
                  }
                  className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-xs font-semibold text-gray-600 transition-colors hover:bg-gray-50 disabled:opacity-50"
                >
                  Sebelumnya
                </button>

                <span className="text-xs font-bold text-gray-700">
                  Halaman {pagination.page}
                </span>

                <button
                  disabled={owners.length < pagination.limit}
                  onClick={() =>
                    setPagination((prev) => ({
                      ...prev,
                      page: prev.page + 1,
                    }))
                  }
                  className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-xs font-semibold text-gray-600 transition-colors hover:bg-gray-50 disabled:opacity-50"
                >
