          { id: 4, tipe: "potensi", label: "✓", keterangan: "Terjadi peningkatan transaksi selama masa penggunaan.", urutan: 4 },
          { id: 5, tipe: "potensi", label: "✓", keterangan: "Memberikan rekomendasi rekan atau mitra.", urutan: 5 },
