            subtitle="Relasi customer dan outlet yang menggunakan subscription"
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />}
          >
            <FieldBox label="ID Owner" value={subscription.owner?.id ?? "-"} />
            <FieldBox label="Kode Owner" value={subscription.owner?.code || "-"} />
            <FieldBox label="Nama Owner" value={subscription.owner?.name || "-"} />
            <FieldBox label="Outlet ID" value={subscription.outlet_id ?? "-"} />
            <FieldBox label="Kode Outlet" value={outlet?.code || "-"} />
            <FieldBox label="Nama Outlet" value={outlet?.name || "-"} />
            <FieldBox label="Telepon Outlet" value={outlet?.phone || "-"} />
            <FieldBox label="Lokasi Outlet" value={outlet ? [outlet.city, outlet.province].filter(Boolean).join(", ") || "-" : "-"} />
            <FieldBox label="Alamat Outlet" value={outlet?.address || "-"} span />
          </InfoSection>

          <InfoSection
            title="Informasi Order Pembelian"
            subtitle="Snapshot pembelian paket yang melahirkan subscription ini"
            icon={<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 10h18M7 15h1m4 0h1m-9 4h16a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />}
          >
            <FieldBox label="Order ID" value={order?.id ?? subscription.order?.id ?? "-"} />
            <FieldBox label="Kode Order" value={order?.code || subscription.order?.code || "-"} />
            <FieldBox label="Plan" value={subscription.plan?.name || order?.plan?.name || "-"} />
            <FieldBox label="Promotion">
              {order?.promotion?.id ? (
                <Link
                  href={`/menu/paket-langganan/promotions/${order.promotion.id}`}
                  className="text-[#C92C1E] hover:underline"
                >
                  {order.promotion.name || order.promotion.code || `PROMO-${order.promotion.id}`}
                </Link>
              ) : (
                order?.promotion?.name || "-"
              )}
            </FieldBox>
            <FieldBox label="Order Status">
              <Badge value={formatLabel(order?.status)} className={getStatusBadgeClass(order?.status)} />
            </FieldBox>
            <FieldBox label="Wallet Transaction ID" value={order?.wallet_transaction_id ?? "-"} />
            <FieldBox label="Purchased At" value={formatDateTime(order?.purchased_at)} />
            <FieldBox label="Subscription Start Date" value={formatDateOnly(order?.subscription_start_date)} />
            <FieldBox label="Tenure (Bulan)" value={order?.tenure_months ?? "-"} />
            <FieldBox label="Durasi (Hari)" value={order?.duration_days ?? subscription.total_duration_days ?? "-"} />
            <FieldBox label="Base Price" value={formatRupiah(order?.base_price)} />
            <FieldBox label="Additional Charge" value={formatRupiah(order?.additional_charge)} />
            <FieldBox label="Final Amount" value={formatRupiah(order?.final_amount)} />
            <FieldBox label="External Reference" value={order?.external_reference || "-"} />
            <FieldBox label="Closing Ref" value={order?.closing?.code || order?.closing?.id || "-"} />
            <FieldBox label="Catatan Order" value={order?.note || "-"} span />
          </InfoSection>
        </div>
      )}
    </div>
  );
}

